import sys; sys.path.insert(0, __import__('os').path.dirname(__import__('os').path.abspath(__file__)))
from mgen import *
import msvg as S
import math, itertools
from fractions import Fraction as F

T = Topic(5, 'pokhidna')
M = MINUS

# ---------- допоміжне ----------
def pn(v): return f'({fmt(v)})' if F(v) < 0 else fmt(v)
def ev(co, x):
    r = F(0)
    for c in co: r = r * F(x) + c
    return r
def dco(co):
    n = len(co) - 1
    return [c * (n - i) for i, c in enumerate(co[:-1])] or [0]
def ico(co):
    n = len(co)
    return [F(c, n - i) for i, c in enumerate(co)] + [F(0)]
def integ(co, a, b): I_ = ico(co); return ev(I_, b) - ev(I_, a)
def P(co, var='x'): return poly([F(c) for c in co], var)
def tail(b): return f' {"+" if b > 0 else M} {fmt(abs(b))}' if b else ''
def sg(v): return '+' if v >= 0 else M
def setstr(parts):
    out = []
    for lo, hi, lc, rc in parts:
        ls = '(−∞' if lo is None else ('[' if lc else '(') + fmt(lo)
        rs_ = '+∞)' if hi is None else fmt(hi) + (']' if rc else ')')
        out.append(f'{ls}; {rs_}')
    return ' ∪ '.join(out) if out else 'порожня множина'
def I(p, q, lc=True, rc=True): return setstr([(None if p is None else F(p), None if q is None else F(q), lc, rc)])
def rpoly(rng, deg, lo=-6, hi=6, lead=None):
    co = [rng.choice([v for v in range(lo, hi + 1) if v]) if lead is None else lead] + [rng.randint(lo, hi) for _ in range(deg)]
    return co

# ================= L1 =================
def f_d_poly(T, rng, lv):
    deg = rng.choice([3, 3, 4]); co = rpoly(rng, deg, -5, 5)
    if sum(1 for c in co[:-1] if c) < 2 or co[-1] == 0: return False
    d = dco(co); ans = 'f′(x) = ' + P(d)
    w1 = [c for c in co[:-1]]                                   # показник зменшено, коефіцієнти ті самі
    w2 = d[:-1] + [d[-1] + co[-1]]                               # стала залишилась
    w3 = d + [0]                                                 # показник не зменшено
    w4 = [-d[0]] + d[1:]
    w5 = [c * (deg - i + 1) for i, c in enumerate(co[:-1])]      # помножено на показник + 1
    wr = [('f′(x) = ' + P(w2), f'похідна сталої дорівнює 0, тому доданок {fmt(co[-1])} має зникнути'), ('f′(x) = ' + P(w1), 'показники зменшено на 1, але коефіцієнти не помножено на показники'),
          ('f′(x) = ' + P(w3), 'коефіцієнти помножено на показники, але самі показники не зменшено на 1'), ('f′(x) = ' + P(w4), 'знак старшого коефіцієнта змінено'), ('f′(x) = ' + P(w5), 'коефіцієнти помножено на число, на 1 більше за показник')]
    return T.add(lv, f'Знайдіть похідну функції f(x) = {P(co)}.', ans, wr, '(xⁿ)′ = n·xⁿ⁻¹; похідна сталої дорівнює 0; сталий множник виносять за знак похідної', f'диференціюємо кожен доданок: {ans}')

def f_d_point(T, rng, lv):
    co = rpoly(rng, 3, -4, 4); x0 = rng.choice([-3, -2, -1, 1, 2, 3])
    if co[1] == 0 and co[2] == 0: return False
    d = dco(co); ans = ev(d, x0)
    wr = [(ev(co, x0), 'обчислено значення самої функції f(x₀), а не похідної'), (ev(co[:-1], x0), 'показники зменшено, але коефіцієнти не помножено на показники'), (ev(d, -x0), 'підставлено x₀ з протилежним знаком'),
          (ans + co[-1], 'сталий доданок не зник під час диференціювання'), (ev(d + [0], x0), 'показники степенів не зменшено на 1')]
    return T.add(lv, f'Обчисліть f′({fmt(x0)}), якщо f(x) = {P(co)}.', ans, wr, 'спочатку знайдіть похідну як функцію, а потім підставте x₀', f'f′(x) = {P(d)}; f′({fmt(x0)}) = {fmt(ans)}')

# елементарні функції: назва → (шаблон похідної, знак, [(шаблон хибної, знак, причина)])
BAS = {
 'sin x': ('{c}cos x', 1, [('{c}cos x', -1, '(sin x)′ = cos x — без мінуса'), ('{c}sin x', 1, 'синус не продиференційовано')]),
 'cos x': ('{c}sin x', -1, [('{c}sin x', 1, '(cos x)′ = −sin x: пропущено мінус'), ('{c}cos x', 1, 'косинус не продиференційовано')]),
 'eˣ': ('{c}eˣ', 1, [('{c}xeˣ⁻¹', 1, 'eˣ продиференційовано як степеневу функцію xⁿ; насправді (eˣ)′ = eˣ')]),
 'ln x': ('{c}/x', 1, [('{c}/x²', 1, '(ln x)′ = 1/x, а не 1/x²'), ('{c}eˣ', 1, 'логарифм переплутано з показниковою функцією')]),
 'tg x': ('{c}/cos² x', 1, [('{c}/sin² x', 1, '(tg x)′ = 1/cos² x; 1/sin² x стосується котангенса'), ('{c}/cos² x', -1, '(tg x)′ = 1/cos² x — без мінуса')]),
 'ctg x': ('{c}/sin² x', -1, [('{c}/sin² x', 1, '(ctg x)′ = −1/sin² x: пропущено мінус'), ('{c}/cos² x', -1, '1/cos² x стосується тангенса')]),
 '√x': ('{c}/(2√x)', 1, [('{c}/√x', 1, '(√x)′ = 1/(2√x): пропущено 2 у знаменнику'), ('{c}√x', 1, 'корінь не продиференційовано')]),
 '1/x': ('{c}/x²', -1, [('{c}/x²', 1, '(1/x)′ = −1/x²: пропущено мінус'), ('{c}ln x', 1, 'ln x — первісна для 1/x, а не похідна')]),
}
def bterm(pat, c, first):
    """доданок c·pat зі знаком; pat містить {c}"""
    a = abs(c); frac = pat.startswith('{c}/')
    body = pat.replace('{c}', fmt(a) if (frac or a != 1) else '')
    if first: return (M if c < 0 else '') + body
    return (f' {M} ' if c < 0 else ' + ') + body
def fterm(name, c, first):
    a = abs(c)
    body = (f'{fmt(a)}/x' if name == '1/x' else (('' if a == 1 else fmt(a)) + name))
    if first: return (M if c < 0 else '') + body
    return (f' {M} ' if c < 0 else ' + ') + body
def f_d_table(T, rng, lv):
    u, v = rng.sample(list(BAS), 2); a, b = rng.choice([1, 2, 3, 4, 5, -2, -3]), rng.choice([1, 2, 3, 4, -1, -2, -5])
    if lv == 1 and {u, v} & {'ctg x', 'tg x'} and rng.random() < .5: return False
    du, su, wu = BAS[u]; dv, sv, wv = BAS[v]
    mk = lambda p1, s1, p2, s2: 'f′(x) = ' + bterm(p1, a * s1, True) + bterm(p2, b * s2, False)
    ans = mk(du, su, dv, sv); wr = []
    for (p, s_, r) in wu: wr.append((mk(p, s_, dv, sv), f'для першого доданка: {r}'))
    for (p, s_, r) in wv: wr.append((mk(du, su, p, s_), f'для другого доданка: {r}'))
    wr = [wr[0], wr[len(wu)]] + wr[1:len(wu)] + wr[len(wu) + 1:]
    wr.append((mk(wu[0][0], wu[0][1], wv[0][0], wv[0][1]), 'помилки в обох доданках'))
    return T.add(lv, f'Знайдіть похідну функції f(x) = {fterm(u, a, True)}{fterm(v, b, False)}.', ans, wr, 'таблиця похідних: (sin x)′ = cos x, (cos x)′ = −sin x, (eˣ)′ = eˣ, (ln x)′ = 1/x, (√x)′ = 1/(2√x), (1/x)′ = −1/x², (tg x)′ = 1/cos² x, (ctg x)′ = −1/sin² x',
                 f'похідна суми дорівнює сумі похідних: {ans}')

def f_anti_poly(T, rng, lv):
    deg = rng.choice([2, 2, 3]); Fco = [rng.choice([v for v in range(-4, 5) if v])] + [rng.randint(-4, 4) for _ in range(deg - 1)] + [rng.choice([v for v in range(-6, 7) if v])] + [0]
    Fco = [1 * c for c in Fco]                       # F(x) без сталої; f = F′
    if sum(1 for c in Fco if c) < 3: return False
    f = dco(Fco); n = len(f) - 1
    ans = 'F(x) = ' + P(Fco) + ' + C'
    w1 = f + [0]                                     # не поділено на новий показник
    w2 = dco(f)                                      # похідна
    w3 = [F(c, (n - i)) if (n - i) else c for i, c in enumerate(f)] + [0]   # поділено на старий показник
    w4 = Fco[:-2] + [0, Fco[-2]]                     # сталу f не проінтегровано: ∫c dx = c
    wr = [('F(x) = ' + P(w1) + ' + C', 'показники збільшено на 1, але коефіцієнти не поділено на нові показники'), ('F(x) = ' + P(w2) + ' + C', 'знайдено похідну, а не первісну'), ('F(x) = ' + P(w4) + ' + C', f'первісна сталої {fmt(f[-1])} дорівнює {fmt(f[-1])}x, а не {fmt(f[-1])}')]
    if all(F(c).denominator == 1 for c in w3) and w3 != Fco: wr.append(('F(x) = ' + P(w3) + ' + C', 'коефіцієнти поділено на старі показники, а не на нові'))
    wr.append(('F(x) = ' + P([-c for c in Fco]) + ' + C', 'усі знаки змінено на протилежні'))
    return T.add(lv, f'Знайдіть загальний вигляд первісних функції f(x) = {P(f)}.', ans, wr, 'первісна для xⁿ дорівнює xⁿ⁺¹/(n + 1); перевірка — диференціюванням: F′(x) = f(x)', f'{ans}; перевірка: F′(x) = {P(f)}')

def f_int_poly(T, rng, lv):
    for _ in range(200):
        if lv == 1: Fco = [rng.choice([1, 2, 3, -1, -2]), rng.randint(-4, 4), 0]
        else: Fco = [rng.choice([1, 2, -1, -2]), rng.randint(-3, 3), rng.randint(-5, 5), 0]
        a = rng.randint(-2, 2); b = a + rng.randint(1, 3); f = dco(Fco)
        if (lv == 1 and a == 0) or f[-1] == 0: continue
        ans = ev(Fco, b) - ev(Fco, a)
        if ans != 0: break
    w_nodiv = f + [0]
    wr = [(ev(Fco, b) + ev(Fco, a), 'значення первісної на межах додано, а не віднято'), (ev(Fco, a) - ev(Fco, b), 'межі переставлено: віднімати треба F(a) від F(b)'), (ev(f, b) - ev(f, a), 'межі підставлено в саму функцію, а не в первісну'),
          (ev(w_nodiv, b) - ev(w_nodiv, a), 'у первісній коефіцієнти не поділено на нові показники'), (ev(Fco, b), 'обчислено лише F(b), нижню межу не враховано')]
    return T.add(lv, f'Обчисліть інтеграл ∫ ({P(f)}) dx у межах від {fmt(a)} до {fmt(b)}.', ans, wr, 'формула Ньютона — Лейбніца: інтеграл від a до b дорівнює F(b) − F(a), де F — первісна',
                 f'F(x) = {P(Fco)}; F({fmt(b)}) − F({fmt(a)}) = {fmt(ev(Fco, b))} − {pn(ev(Fco, a))} = {fmt(ans)}')

def f_motion(T, rng, lv):
    a, b, c = rng.choice([1, 2, -1]), rng.choice([3, 6, 9, -3, -6, 12]), rng.randint(1, 9); co = [a, b, c, 0]; t0 = rng.randint(1, 4)
    v = dco(co); acc = dco(v)
    if lv == 1:
        ans = ev(v, t0)
        if ans <= 0: return False
        wr = [(ev(co, t0), 'знайдено шлях s(t₀), а не швидкість'), (ev(acc, t0), 'знайдено прискорення (другу похідну)'), (F(ev(co, t0), t0), 'шлях поділено на час — це середня швидкість, а не миттєва'), (ev(co[:-1], t0), 'коефіцієнти не помножено на показники'), (ans + c, 'помилка в диференціюванні лінійного доданка')]
        return T.add(lv, f'Матеріальна точка рухається прямолінійно за законом s(t) = {P(co, "t")} (s — у метрах, t — у секундах). Знайдіть її швидкість (у м/с) у момент часу t = {t0} с.', ans, wr, 'миттєва швидкість — похідна шляху за часом: v(t) = s′(t)', f'v(t) = {P(v, "t")}; v({t0}) = {fmt(ans)}')
    if lv == 2:
        kind = rng.choice(['acc', 'stop'])
        if kind == 'acc':
            ans = ev(acc, t0)
            wr = [(ev(v, t0), 'знайдено швидкість (першу похідну), а не прискорення'), (ev(co, t0), 'знайдено шлях'), (F(ev(v, t0), t0), 'швидкість поділено на час'), (acc[0], 'узято лише коефіцієнт при t у формулі прискорення'), (-ans, 'знак змінено')]
            return T.add(lv, f'Матеріальна точка рухається прямолінійно за законом s(t) = {P(co, "t")} (s — у метрах, t — у секундах). Знайдіть її прискорення (у м/с²) у момент часу t = {t0} с.', ans, wr, 'прискорення — похідна швидкості, тобто друга похідна шляху: a(t) = v′(t) = s″(t)', f'v(t) = {P(v, "t")}; a(t) = {P(acc, "t")}; a({t0}) = {fmt(ans)}')
        p, q = rng.randint(1, 3), rng.randint(4, 7); co2 = [1, F(-3 * (p + q), 2), 3 * p * q, 0]
        if (p + q) % 2: return False
        v2 = dco(co2)
        wr = [(F(q), 'узято другий (пізніший) момент зупинки'), (F(p + q, 2), 'знайдено момент, коли прискорення дорівнює нулю'), (F(p + q), 'знайдено суму моментів зупинки'), (F(p * q), 'знайдено добуток коренів'), (F(3 * p * q), 'узято вільний член формули швидкості')]
        return T.add(lv, f'Матеріальна точка рухається прямолінійно за законом s(t) = {P(co2, "t")} (t ≥ 0, t — у секундах). У який момент часу (у секундах) точка вперше зупиниться?', F(p), wr, 'у момент зупинки швидкість дорівнює нулю: v(t) = s′(t) = 0', f'v(t) = {P(v2, "t")} = 3(t − {p})(t − {q}) = 0 ⇒ t = {p} або t = {q}; уперше — при t = {p}')
    # L3: швидкість у момент, коли прискорення дорівнює нулю / найменша швидкість
    k = rng.randint(1, 4); c3 = rng.randint(3 * k * k + 1, 3 * k * k + 12); co3 = [1, -3 * k, c3, 0]; v3 = dco(co3); a3 = dco(v3)
    ans = ev(v3, k)
    wr = [(F(c3), 'узято швидкість у початковий момент t = 0'), (F(k), 'названо момент часу, а не швидкість'), (ev(co3, k), 'знайдено шлях у цей момент'), (ev(v3, 2 * k), 'момент часу знайдено неправильно (t = ' + str(2 * k) + ')'), (F(0), 'прирівняно до нуля швидкість замість прискорення')]
    q = rng.choice(['У момент, коли прискорення точки дорівнює нулю, знайдіть її швидкість (у м/с).', 'Знайдіть найменшу швидкість руху точки (у м/с).'])
    return T.add(lv, f'Матеріальна точка рухається прямолінійно за законом s(t) = {P(co3, "t")} (s — у метрах, t ≥ 0 — у секундах). ' + q, ans, wr, 'v(t) = s′(t), a(t) = v′(t); найменша швидкість досягається там, де a(t) = 0 (вершина параболи v(t))',
                 f'v(t) = {P(v3, "t")}; a(t) = {P(a3, "t")} = 0 ⇒ t = {k}; v({k}) = {fmt(ans)}')

def f_tangent_slope(T, rng, lv):
    co = rpoly(rng, rng.choice([2, 3]), -4, 4); x0 = rng.choice([-2, -1, 1, 2, 3]); d = dco(co); k = ev(d, x0)
    if lv == 1:
        wr = [(ev(co, x0), 'знайдено ординату точки дотику f(x₀), а не кутовий коефіцієнт'), (-k, 'знак змінено'), (ev(d, 0), 'похідну обчислено в точці 0, а не в x₀'), (ev(co[:-1], x0), 'коефіцієнти не помножено на показники'), (F(x0), 'названо абсцису точки дотику')]
        return T.add(lv, f'Знайдіть кутовий коефіцієнт дотичної до графіка функції y = {P(co)} у точці з абсцисою x₀ = {fmt(x0)}.', k, wr, 'кутовий коефіцієнт дотичної дорівнює значенню похідної в точці дотику: k = f′(x₀)', f'y′ = {P(d)}; k = y′({fmt(x0)}) = {fmt(k)}')
    # L2: кут нахилу дотичної
    for _ in range(300):
        co = rpoly(rng, 2, -4, 4); x0 = rng.randint(-3, 3); d = dco(co); k = ev(d, x0)
        if k in (1, -1): break
    else: return False
    ans = 45 if k == 1 else 135
    wr = [(180 - ans, f'знак похідної не враховано: f′(x₀) = {fmt(k)}, тому кут {"гострий" if k == 1 else "тупий"}'), (60, 'tg 60° = √3, а не 1'), (30, 'tg 30° = √3/3, а не 1'), (90, 'дотична не вертикальна: tg 90° не існує'), (0, 'кут 0° відповідав би f′(x₀) = 0')]
    return T.add(lv, f'Знайдіть кут (у градусах), який утворює з додатним напрямом осі x дотична до графіка функції y = {P(co)} у точці з абсцисою x₀ = {fmt(x0)}.', ans, wr, 'tg α = f′(x₀); якщо похідна від’ємна, кут тупий: α = 180° − arctg|f′(x₀)|', f'y′ = {P(d)}; y′({fmt(x0)}) = {fmt(k)} = tg α ⇒ α = {ans}°')

def cubic_pq(rng, lead=1):
    """f = lead·(x³ − 1,5(p+q)x² + 3pqx) + c, f′ = 3·lead·(x − p)(x − q), p < q цілі однакової парності"""
    while True:
        p = rng.randint(-4, 3); q = p + rng.choice([2, 4, 6])
        if q <= 5: break
    c = rng.randint(-5, 5)
    return p, q, [lead, lead * F(-3 * (p + q), 2), lead * 3 * p * q, c]
def f_crit(T, rng, lv):
    lead = rng.choice([1, 1, -1]) if lv > 1 else 1; p, q, co = cubic_pq(rng, lead); d = dco(co)
    fs = f'f(x) = {P(co)}'; fact = f'f′(x) = {P(d)} = {fmt(3 * lead)}(x {sg(-p)} {abs(p)})(x {sg(-q)} {abs(q)})'.replace('(x + 0)', 'x').replace('(x − 0)', 'x')
    xmax, xmin = (p, q) if lead > 0 else (q, p)
    if lv == 1:
        kind = rng.choice(['sum', 'prod'])
        if kind == 'sum':
            wr = [(F(p * q), 'знайдено добуток критичних точок'), (F(-(p + q)), 'знак змінено: за теоремою Вієта сума коренів дорівнює −b/a'), (F(3 * (p + q), 2), 'корені похідної знайдено без ділення на старший коефіцієнт'), (F(q - p), 'знайдено різницю критичних точок'), (F(3 * (p + q)), 'узято коефіцієнт при x у похідній із протилежним знаком')]
            return T.add(lv, f'Знайдіть суму критичних точок функції {fs}.', F(p + q), wr, 'критичні точки — внутрішні точки області визначення, у яких похідна дорівнює нулю або не існує', fact + f' = 0 ⇒ x = {fmt(p)}, x = {fmt(q)}; сума {fmt(p + q)}')
        wr = [(F(p + q), 'знайдено суму критичних точок'), (F(-p * q), 'знак змінено'), (F(3 * p * q), 'узято вільний член похідної без ділення на старший коефіцієнт'), (F(9 * p * q), 'вільний член похідної помножено на старший коефіцієнт'), (F(p * q + 1), 'помилка в обчисленні коренів')]
        if p * q == 0: return False
        return T.add(lv, f'Знайдіть добуток критичних точок функції {fs}.', F(p * q), wr[:4], 'критичні точки — внутрішні точки області визначення, у яких похідна дорівнює нулю або не існує', fact + f' = 0 ⇒ x = {fmt(p)}, x = {fmt(q)}; добуток {fmt(p * q)}')
    kind = rng.choice(['xmax', 'xmin', 'ymax', 'ymin', 'dec', 'inc'])
    trap = 'точка максимуму — там, де похідна змінює знак з «+» на «−»; точка мінімуму — з «−» на «+»; це значення x, а не y'
    signs = f'знаки f′: {"+ − +" if lead > 0 else "− + −"} (точки {fmt(p)} і {fmt(q)})'
    if kind in ('xmax', 'xmin'):
        ans, oth = (xmax, xmin) if kind == 'xmax' else (xmin, xmax)
        wr = [(F(oth), f'названо точку {"мінімуму" if kind == "xmax" else "максимуму"}: знаки похідної визначено навпаки'), (ev(co, ans), 'названо значення функції в цій точці (екстремум), а не саму точку'), (F(p + q, 2), 'названо середину між критичними точками'), (F(-ans), 'знак змінено'), (F(p + q), 'названо суму критичних точок')]
        return T.add(lv, f'Знайдіть точку {"максимуму" if kind == "xmax" else "мінімуму"} функції {fs}.', F(ans), wr, trap, fact + '; ' + signs + f'; точка {"максимуму" if kind == "xmax" else "мінімуму"} x = {fmt(ans)}')
    if kind in ('ymax', 'ymin'):
        xa, xo = (xmax, xmin) if kind == 'ymax' else (xmin, xmax); ans = ev(co, xa)
        wr = [(ev(co, xo), f'знайдено {"мінімум" if kind == "ymax" else "максимум"} функції'), (F(xa), 'названо точку екстремуму (x), а не значення функції'), (F(co[-1]), 'узято значення f(0)'), (ev(d, xa) + ans + 1, 'помилка в обчисленні значення функції'), (-ans, 'знак змінено')]
        return T.add(lv, f'Знайдіть {"максимум" if kind == "ymax" else "мінімум"} функції {fs} (значення функції в точці {"максимуму" if kind == "ymax" else "мінімуму"}).', ans, wr[:3] + wr[4:], 'спочатку знайдіть точку екстремуму, а потім обчисліть у ній значення функції', fact + '; ' + signs + f'; x = {fmt(xa)}; f({fmt(xa)}) = {fmt(ans)}')
    inner = (kind == 'dec') == (lead > 0)
    ans = I(p, q) if inner else setstr([(None, F(p), False, True), (F(q), None, True, False)]).replace(' ∪ ', ' і ')
    other = setstr([(None, F(p), False, True), (F(q), None, True, False)]).replace(' ∪ ', ' і ') if inner else I(p, q)
    wr = [(other, f'на цих проміжках функція {"зростає" if kind == "dec" else "спадає"}: знаки похідної визначено навпаки'), (I(-q, -p) if inner else setstr([(None, F(-q), False, True), (F(-p), None, True, False)]).replace(' ∪ ', ' і '), 'знаки критичних точок змінено'),
          (I(ev(co, xmin), ev(co, xmax)), 'проміжок записано значеннями функції (y), а не аргументу (x)'), (I(p, None) if inner else I(None, q, False, True), 'враховано лише одну критичну точку')]
    return T.add(lv, f'Укажіть проміжок (проміжки) {"спадання" if kind == "dec" else "зростання"} функції {fs}.', ans, wr, 'функція зростає там, де f′(x) ≥ 0, і спадає там, де f′(x) ≤ 0', fact + '; ' + signs + f'; відповідь: {ans}')

INTB = [  # (підінтегральна, нижня, верхня, F(a), F(b), f(a), f(b), первісна)
 ('sin x', '0', 'π', -1, 1, 0, 0, '−cos x'), ('sin x', '0', 'π/2', -1, 0, 0, 1, '−cos x'), ('cos x', '0', 'π/2', 0, 1, 1, 0, 'sin x'), ('cos x', '−π/2', 'π/2', -1, 1, 0, 0, 'sin x'),
 ('sin x', 'π/2', 'π', 0, 1, 1, 0, '−cos x'), ('cos x', 'π/2', 'π', 1, 0, 0, -1, 'sin x'), ('1/x', '1', 'e', 0, 1, 1, None, 'ln x'), ('1/x', '1', 'e²', 0, 2, 1, None, 'ln x'), ('1/x', 'e', 'e³', 1, 3, None, None, 'ln x'),
 ('eˣ', '0', 'ln 3', 1, 3, 1, 3, 'eˣ'), ('eˣ', '0', 'ln 5', 1, 5, 1, 5, 'eˣ'), ('eˣ', 'ln 2', 'ln 6', 2, 6, 2, 6, 'eˣ'), ('1/cos² x', '0', 'π/4', 0, 1, 1, 2, 'tg x'), ('sin x', 'π', '2π', 1, -1, 0, 0, '−cos x'), ('cos x', '0', 'π', 0, 0, 1, -1, 'sin x')]
def f_int_basic(T, rng, lv):
    fs, a, b, Fa, Fb, fa, fb, Fn = rng.choice(INTB); k = rng.choice([1, 2, 3, 4, 5, 6] if lv == 1 else [2, 3, 4, 5, 6, 8, 10])
    ans = k * (Fb - Fa)
    wr = [(k * (Fa - Fb), 'межі переставлено: потрібно F(b) − F(a)'), (k * (Fb + Fa), 'значення первісної на межах додано замість віднімання'), (k * Fb, 'нижню межу не враховано: обчислено лише F(b)')]
    if fa is not None and fb is not None: wr.insert(1, (k * (fb - fa), 'межі підставлено в саму функцію, а не в первісну'))
    wr += [(F(Fb - Fa), f'пропущено сталий множник {k}') if k != 1 else (F(ans) * 2, 'результат подвоєно'), (F(k), 'названо сталий множник'), (F(0), 'інтеграл помилково прийнято рівним нулю')]
    ks = '' if k == 1 else str(k)
    integrand = (f'{k}/x' if fs == '1/x' else (f'{k}/cos² x' if fs == '1/cos² x' else ks + fs))
    return T.add(lv, f'Обчисліть інтеграл ∫ {integrand} dx у межах від {a} до {b}.', ans, wr, f'первісна: {Fn}; далі формула Ньютона — Лейбніца F(b) − F(a)',
                 'F(x) = ' + ((M + ks + Fn[1:]) if Fn.startswith(M) else ks + Fn) + f'; F({b}) − F({a}) = {fmt(k * Fb)} − {pn(k * Fa)} = {fmt(ans)}')

def f_second(T, rng, lv):
    co = rpoly(rng, rng.choice([3, 4]), -3, 3); x0 = rng.choice([-2, -1, 1, 2]); d1 = dco(co); d2 = dco(d1); ans = ev(d2, x0)
    if all(c == 0 for c in d2[:-1]): return False
    wr = [(ev(d1, x0), 'знайдено першу похідну, а не другу'), (ev(co, x0), 'знайдено значення функції'), (ev(d1, x0) ** 2, 'першу похідну піднесено до квадрата замість повторного диференціювання'), (ev(dco(d2), x0), 'знайдено третю похідну'), (ev(d2, -x0), 'підставлено x₀ з протилежним знаком')]
    return T.add(lv, f'Знайдіть значення другої похідної f″({fmt(x0)}), якщо f(x) = {P(co)}.', ans, wr, 'друга похідна — це похідна від першої похідної: f″(x) = (f′(x))′', f'f′(x) = {P(d1)}; f″(x) = {P(d2)}; f″({fmt(x0)}) = {fmt(ans)}')

# ================= L2 =================
def f_d_product(T, rng, lv):
    kind = rng.choice(['poly', 'poly', 'exp', 'ln', 'sin'])
    if kind == 'poly':
        a, b, c, d = rng.choice([1, 2, 3]), rng.choice([-4, -3, -2, -1, 1, 2, 3]), rng.choice([1, 2, -1]), rng.choice([-5, -3, -1, 1, 2, 4]); x0 = rng.choice([-2, -1, 1, 2])
        u, v = [a, b], [c, 0, d]; du, dv = dco(u), dco(v); U, V, DU, DV = ev(u, x0), ev(v, x0), ev(du, x0), ev(dv, x0)
        ans = DU * V + U * DV
        wr = [(DU * DV, 'похідну добутку замінено добутком похідних; правильно (uv)′ = u′v + uv′'), (DU * V - U * DV, 'у формулі взято мінус, як для частки'), (DU * V, 'обчислено лише перший доданок u′v'), (U * V, 'знайдено значення функції, а не похідної'), (U * DV, 'обчислено лише другий доданок uv′')]
        return T.add(lv, f'Обчисліть f′({fmt(x0)}), якщо f(x) = ({P(u)})({P(v)}).', ans, wr, '(uv)′ = u′v + uv′ — похідна добутку не дорівнює добутку похідних', f'u = {P(u)}, v = {P(v)}; u′ = {P(du)}, v′ = {P(dv)}; f′({fmt(x0)}) = {fmt(DU)}·{pn(V)} + {pn(U)}·{pn(DV)} = {fmt(ans)}')
    a = rng.randint(2, 7)
    if kind == 'exp':
        ans = 1 + a
        wr = [(1, 'похідну добутку замінено добутком похідних: 1·e⁰'), (a, 'знайдено f(0) або лише доданок uv′'), (1 - a, 'у формулі взято мінус, як для частки'), (a + 2, 'похідну eˣ у точці 0 обчислено неправильно')]
        return T.add(lv, f'Обчисліть f′(0), якщо f(x) = (x + {a})·eˣ.', ans, wr, '(uv)′ = u′v + uv′; (eˣ)′ = eˣ, e⁰ = 1', f'f′(x) = eˣ + (x + {a})eˣ = (x + {a + 1})eˣ; f′(0) = {a + 1}')
    if kind == 'ln':
        ans = 1 + a * 0 + a  # f = (x + a)·ln x у точці 1: ln 1 + (1 + a)/1
        ans = 1 + a
        wr = [(1, 'похідну добутку замінено добутком похідних: 1·(1/1)'), (0, 'знайдено f(1) = 0'), (a, 'у доданку uv′ узято u = ' + str(a) + ' замість ' + str(a + 1)), (a + 2, 'ln 1 прийнято рівним 1, хоча ln 1 = 0')]
        return T.add(lv, f'Обчисліть f′(1), якщо f(x) = (x + {a})·ln x.', ans, wr, '(uv)′ = u′v + uv′; (ln x)′ = 1/x, ln 1 = 0', f'f′(x) = ln x + (x + {a})/x; f′(1) = 0 + {a + 1} = {a + 1}')
    ans = a   # f = (ax + 1)·cos x у точці 0: a·cos 0 − (1)·sin 0 = a
    b = rng.randint(1, 5)
    wr = [(0, 'похідну добутку замінено добутком похідних: a·(−sin 0) = 0'), (b, 'знайдено f(0)'), (a + b, 'sin 0 прийнято рівним 1'), (a - b, 'sin 0 прийнято рівним 1'), (-a, 'знак змінено')]
    return T.add(lv, f'Обчисліть f′(0), якщо f(x) = ({a}x + {b})·cos x.', ans, wr, '(uv)′ = u′v + uv′; (cos x)′ = −sin x, cos 0 = 1, sin 0 = 0', f'f′(x) = {a}cos x − ({a}x + {b})sin x; f′(0) = {a}·1 − {b}·0 = {a}')

def f_d_quot(T, rng, lv):
    for _ in range(200):
        a, b, c, d = rng.randint(1, 5), rng.randint(-5, 5), rng.randint(1, 3), rng.randint(-4, 4); x0 = rng.randint(-2, 3)
        den = c * x0 + d; num = a * d - b * c
        if den in (1, -1, 2, -2) and num != 0 and b != 0 and d != 0: break
    else: return False
    ans = F(num, den * den)
    wr = [(F(-num, den * den), 'у чисельнику формули переплутано порядок: потрібно u′v − uv′'), (F(a, c), 'похідну частки замінено часткою похідних u′/v′'), (F(num, den), 'знаменник не піднесено до квадрата'), (F(a * d + b * c, den * den) if a * x0 + b else F(a, den), 'у чисельнику взято плюс, як для добутку'), (F(a * x0 + b, den), 'знайдено значення функції, а не похідної')]
    return T.add(lv, f'Обчисліть f′({fmt(x0)}), якщо f(x) = ({P([a, b])})/({P([c, d])}).', ans, wr, '(u/v)′ = (u′v − uv′)/v² — похідна частки не дорівнює частці похідних',
                 f'f′(x) = ({a}({P([c, d])}) − {c}({P([a, b])}))/({P([c, d])})² = {fmt(num)}/({P([c, d])})²; f′({fmt(x0)}) = {fmt(num)}/{den * den} = {fmt(ans)}')

def f_d_chain(T, rng, lv):
    kind = rng.choice(['pow', 'pow', 'sqrt', 'trig', 'ln'] if lv == 2 else ['pow2', 'ln2', 'sin2', 'prodchain', 'sqrt2'])
    if kind == 'pow':
        a, n = rng.choice([2, 3, -2, 4, 5]), rng.choice([3, 4, 5]); x0 = rng.choice([-1, 0, 1, 2]); b = rng.choice([v for v in range(-14, 15) if abs(a * x0 + v) in (1, 2)]); t = a * x0 + b
        ans = n * a * t ** (n - 1)
        wr = [(n * t ** (n - 1), f'не помножено на похідну внутрішньої функції ({fmt(a)})'), (a * t ** (n - 1), 'не помножено на показник степеня'), (n * a * t ** n, 'показник степеня не зменшено на 1'), (F(t ** n), 'знайдено значення функції, а не похідної'), (n * a * b ** (n - 1), 'похідну обчислено при x = 0')]
        return T.add(lv, f'Обчисліть f′({fmt(x0)}), якщо f(x) = ({P([a, b])}){sup(n)}.', ans, wr, 'похідна складеної функції: (uⁿ)′ = n·uⁿ⁻¹·u′ — не забувайте множити на похідну внутрішньої функції', f'f′(x) = {n}·({P([a, b])}){sup(n - 1)}·{pn(a)}; f′({fmt(x0)}) = {n}·{pn(t)}{sup(n - 1)}·{pn(a)} = {fmt(ans)}')
    if kind == 'sqrt':
        r = rng.choice([1, 2, 3, 4, 5]); a = rng.choice([2, 4, 6, 8]); x0 = rng.choice([0, 1, 2, 3]); b = r * r - a * x0
        ans = F(a, 2 * r)
        wr = [(F(1, 2 * r), f'не помножено на похідну внутрішньої функції ({a})'), (F(a, r), 'пропущено 2 у знаменнику: (√u)′ = u′/(2√u)'), (F(r), 'знайдено значення функції, а не похідної'), (F(a, 2 * r * r), 'у знаменнику взято підкореневий вираз замість кореня'), (F(a * r, 2), 'корінь потрапив у чисельник замість знаменника')]
        return T.add(lv, f'Обчисліть f′({fmt(x0)}), якщо f(x) = √({P([a, b])}).', ans, wr, '(√u)′ = u′/(2√u)', f'f′(x) = {a}/(2√({P([a, b])})); f′({fmt(x0)}) = {a}/(2·{r}) = {fmt(ans)}')
    if kind == 'trig':
        k = rng.choice([2, 3, 4, 5, 6]); which = rng.choice(['sin0', 'cos', 'exp', 'sinpi'])
        if which == 'sin0':
            wr = [(1, f'не помножено на похідну внутрішньої функції ({k})'), (0, 'знайдено f(0) = sin 0'), (-k, '(sin u)′ = cos u·u′ — без мінуса'), (F(1, k), 'поділено на k замість множення')]
            return T.add(lv, f'Обчисліть f′(0), якщо f(x) = sin {k}x.', k, wr, '(sin kx)′ = k·cos kx', f'f′(x) = {k}cos {k}x; f′(0) = {k}·1 = {k}')
        if which == 'cos':
            wr = [(k, '(cos u)′ = −sin u·u′: пропущено мінус'), (-1, f'не помножено на похідну внутрішньої функції ({k})'), (0, 'знайдено значення функції cos(π/2) = 0'), (F(-1, k), 'поділено на k замість множення'), (1, 'пропущено і мінус, і множник k')]
            return T.add(lv, f'Обчисліть f′(π/{2 * k}), якщо f(x) = cos {k}x.', -k, wr, '(cos kx)′ = −k·sin kx', f'f′(x) = −{k}sin {k}x; f′(π/{2 * k}) = −{k}·sin(π/2) = −{k}')
        if which == 'exp':
            wr = [(1, f'не помножено на похідну показника ({k})'), (0, 'похідну сталої e⁰ = 1 прийнято за відповідь'), (F(1, k), 'поділено на k — так роблять під час інтегрування'), (k + 1, 'до k додано значення e⁰')]
            return T.add(lv, f'Обчисліть f′(0), якщо f(x) = e^({k}x).', k, wr, '(e^(kx))′ = k·e^(kx)', f'f′(x) = {k}e^({k}x); f′(0) = {k}·e⁰ = {k}')
        wr = [(k, 'cos π = −1, а не 1'), (-1, f'не помножено на похідну внутрішньої функції ({k})'), (0, 'знайдено значення функції sin π = 0'), (1, 'пропущено множник k і неправильно визначено знак cos π')]
        return T.add(lv, f'Обчисліть f′(π/{k}), якщо f(x) = sin {k}x.', -k, wr, '(sin kx)′ = k·cos kx; cos π = −1', f'f′(x) = {k}cos {k}x; f′(π/{k}) = {k}·cos π = −{k}')
    if kind == 'ln':
        k = rng.choice([2, 3, 4, 5]); x0 = rng.choice([1, 2, 3]); b = rng.choice([v for v in range(-16, 17) if k * x0 + v in (1, 2, 4, 5, 10)]); t = k * x0 + b
        ans = F(k, t)
        wr = [(F(1, t), f'не помножено на похідну внутрішньої функції ({k})'), (F(t, k), 'дріб перевернуто'), (F(k * t), 'помножено на внутрішню функцію замість ділення'), (F(1, x0), 'використано (ln x)′ = 1/x без урахування внутрішньої функції'), (F(k), 'названо лише похідну внутрішньої функції')]
        return T.add(lv, f'Обчисліть f′({x0}), якщо f(x) = ln({P([k, b])}).', ans, wr, '(ln u)′ = u′/u', f'f′(x) = {k}/({P([k, b])}); f′({x0}) = {k}/{t} = {fmt(ans)}')
    if kind == 'pow2':
        n = rng.choice([2, 3, 4]); x0 = rng.choice([-2, -1, 1, 2]); c = rng.choice([v for v in range(-6, 7) if abs(x0 * x0 + v) in (1, 2)]); t = x0 * x0 + c
        ans = n * t ** (n - 1) * 2 * x0
        wr = [(n * t ** (n - 1), 'не помножено на похідну внутрішньої функції 2x'), (n * t ** (n - 1) * 2, 'похідну внутрішньої функції взято рівною 2, а не 2x'), (F(t ** n), 'знайдено значення функції'), (n * t ** n * 2 * x0, 'показник степеня не зменшено'), (-ans, 'знак змінено')]
        return T.add(lv, f'Обчисліть f′({fmt(x0)}), якщо f(x) = ({P([1, 0, c])}){sup(n)}.', ans, wr, '(uⁿ)′ = n·uⁿ⁻¹·u′, де u = x² + c, u′ = 2x', f'f′(x) = {n}({P([1, 0, c])}){sup(n - 1)}·2x; f′({fmt(x0)}) = {n}·{pn(t)}{sup(n - 1)}·{pn(2 * x0)} = {fmt(ans)}')
    if kind == 'ln2':
        x0 = rng.choice([1, 2, 3, -1, -2]); c = rng.choice([v for v in range(1, 12) if (x0 * x0 + v) in (2, 4, 5, 8, 10)]); t = x0 * x0 + c
        ans = F(2 * x0, t)
        wr = [(F(1, t), 'не помножено на похідну внутрішньої функції 2x'), (F(2, t), 'похідну внутрішньої функції взято рівною 2, а не 2x'), (F(t, 2 * x0), 'дріб перевернуто'), (F(x0, t), 'похідну x² взято рівною x'), (-ans, 'знак змінено')]
        return T.add(lv, f'Обчисліть f′({fmt(x0)}), якщо f(x) = ln(x² + {c}).', ans, wr, '(ln u)′ = u′/u, де u = x² + c', f'f′(x) = 2x/(x² + {c}); f′({fmt(x0)}) = {fmt(2 * x0)}/{t} = {fmt(ans)}')
    if kind == 'sin2':
        which = rng.choice(['sin2', 'cos2', 'sin2k'])
        if which == 'sin2':
            k = rng.choice([2, 4, 6, 8])
            wr = [(F(k, 2), 'обчислено f(π/4), а не похідну'), (F(2 * k), 'sin(π/2) подвоєно зайвий раз'), (F(0), 'похідну sin² x прийнято рівною cos² x − sin² x'), (F(k) * F(1, 2), 'пропущено множник 2 із показника'), (F(-k), 'знак змінено')]
            return T.add(lv, f'Обчисліть f′(π/4), якщо f(x) = {k}sin² x.', F(k), wr[:1] + wr[1:3] + wr[4:], '(sin² x)′ = 2 sin x·cos x = sin 2x', f'f′(x) = {k}·2 sin x cos x = {k}sin 2x; f′(π/4) = {k}·sin(π/2) = {k}')
        if which == 'cos2':
            k = rng.choice([2, 4, 6, 8])
            wr = [(F(k), '(cos² x)′ = −sin 2x: пропущено мінус'), (F(k, 2), 'обчислено f(π/4)'), (F(-2 * k), 'зайвий множник 2'), (F(0), 'похідну прийнято рівною нулю'), (F(-k, 2), 'пропущено множник 2 із показника')]
            return T.add(lv, f'Обчисліть f′(π/4), якщо f(x) = {k}cos² x.', F(-k), wr, '(cos² x)′ = 2 cos x·(−sin x) = −sin 2x', f'f′(x) = −{k}sin 2x; f′(π/4) = −{k}')
        k = rng.choice([2, 3, 4])
        wr = [(F(1), 'не враховано множник 2 від показника та множник k від аргументу'), (F(2), 'не враховано множник k від аргументу'), (F(k), 'не враховано множник 2 від показника'), (F(0), 'обчислено sin у точці, де він дорівнює 0, замість sin 2kx'), (F(-2 * k), 'знак змінено')]
        return T.add(lv, f'Обчисліть f′(π/{4 * k}), якщо f(x) = sin² {k}x.', F(k), wr[:2] + wr[3:], '(sin² kx)′ = 2 sin kx·cos kx·k = k·sin 2kx', f'f′(x) = {k}sin {2 * k}x; f′(π/{4 * k}) = {k}·sin(π/2) = {k}')
    if kind == 'prodchain':
        r = rng.choice([1, 2, 3]); x0 = rng.choice([1, 2, 3, 4]); a = 2; b = r * r - a * x0
        ans = F(r) + F(x0 * a, 2 * r)
        wr = [(F(a, 2 * r), 'похідну добутку замінено добутком похідних'), (F(r), 'обчислено лише доданок u′v'), (F(x0 * a, 2 * r), 'обчислено лише доданок uv′'), (F(r) + F(x0, 2 * r), f'не помножено на похідну внутрішньої функції ({a})'), (F(x0 * r), 'знайдено значення функції')]
        return T.add(lv, f'Обчисліть f′({x0}), якщо f(x) = x·√({P([a, b])}).', ans, wr, '(uv)′ = u′v + uv′, причому (√u)′ = u′/(2√u)', f'f′(x) = √({P([a, b])}) + x·{a}/(2√({P([a, b])})); f′({x0}) = {r} + {x0}·{a}/(2·{r}) = {fmt(ans)}')
    r = rng.choice([2, 3, 4, 5]); x0 = rng.choice([1, 2, 3, 4]); c = r * r - x0 * x0
    if c == 0: return False
    ans = F(x0, r)
    wr = [(F(1, 2 * r), 'не помножено на похідну внутрішньої функції 2x'), (F(2 * x0, r), 'двійки не скорочено: (√u)′ = u′/(2√u)'), (F(r, x0), 'дріб перевернуто'), (F(r), 'знайдено значення функції'), (F(1, r), 'похідну x² взято рівною 2, а не 2x')]
    return T.add(lv, f'Обчисліть f′({x0}), якщо f(x) = √(x² {sg(c)} {abs(c)}).', ans, wr, '(√u)′ = u′/(2√u), де u′ = 2x', f'f′(x) = 2x/(2√(x² {sg(c)} {abs(c)})) = x/√(x² {sg(c)} {abs(c)}); f′({x0}) = {x0}/{r} = {fmt(ans)}')

def lin_s(k, b): return 'y = ' + P([k, b])
def f_tangent_eq(T, rng, lv):
    for _ in range(200):
        co = rpoly(rng, rng.choice([2, 2, 3]), -3, 3); x0 = rng.choice([-2, -1, 1, 2]); d = dco(co); k = ev(d, x0); y0 = ev(co, x0); b = y0 - k * x0
        if k != 0 and b != 0 and b != y0 and abs(b) < 40: break
    else: return False
    wr = [(lin_s(k, y0), 'вільний член не обчислено: замість f(x₀) − f′(x₀)·x₀ записано f(x₀)'), (lin_s(k, -b), 'знак вільного члена змінено'), (lin_s(k, y0 + k * x0), 'у рівнянні y = f(x₀) + f′(x₀)(x − x₀) взято (x + x₀)'), (lin_s(y0, k), 'значення функції та похідної переплутано місцями'), (lin_s(-k, y0 + k * x0), 'знак кутового коефіцієнта змінено')]
    return T.add(lv, f'Складіть рівняння дотичної до графіка функції f(x) = {P(co)} у точці з абсцисою x₀ = {fmt(x0)}.', lin_s(k, b), wr, 'рівняння дотичної: y = f(x₀) + f′(x₀)(x − x₀)', f'f({fmt(x0)}) = {fmt(y0)}; f′(x) = {P(d)}, f′({fmt(x0)}) = {fmt(k)}; y = {fmt(y0)} + {pn(k)}(x {sg(-x0)} {abs(x0)}) = {P([k, b])}')

def f_tangent_par(T, rng, lv):
    if lv == 2:
        for _ in range(200):
            a, b, c = rng.choice([1, 2, 3, -1, -2]), rng.randint(-6, 6), rng.randint(-5, 5); k = rng.randint(-8, 8); m = rng.randint(-5, 5)
            x0 = F(k - b, 2 * a)
            if x0.denominator == 1 and b != 0 and k != 0 and x0 != 0: break
        else: return False
        kind = rng.choice(['x', 'y'])
        if kind == 'x':
            wr = [(F(k + b, 2 * a), 'знак b змінено під час перенесення'), (F(k, 2 * a), 'коефіцієнт b не враховано'), (F(k - b, a), 'похідну ax² взято рівною ax, а не 2ax'), (F(k), 'названо кутовий коефіцієнт, а не абсцису'), (F(-b, 2 * a), 'знайдено вершину параболи (f′ = 0), а не точку з f′ = k')]
            return T.add(lv, f'У якій точці графіка функції y = {P([a, b, c])} дотична паралельна прямій y = {P([k, m])}? У відповіді вкажіть абсцису цієї точки.', x0, wr, 'паралельні прямі мають однакові кутові коефіцієнти: f′(x₀) = k', f'y′ = {P([2 * a, b])} = {fmt(k)} ⇒ x₀ = {fmt(x0)}')
        y0 = ev([a, b, c], x0)
        wr = [(x0, 'названо абсцису точки дотику, а не ординату'), (ev([k, m], x0), 'абсцису підставлено в рівняння прямої, а не у функцію'), (F(k), 'названо кутовий коефіцієнт'), (ev([a, b, c], F(-b, 2 * a)) if F(-b, 2 * a).denominator == 1 else y0 + 1, 'знайдено ординату вершини параболи'), (F(c), 'узято f(0)')]
        return T.add(lv, f'Дотична до графіка функції y = {P([a, b, c])} паралельна прямій y = {P([k, m])}. Знайдіть ординату точки дотику.', y0, wr[:3] + wr[4:], 'спочатку з рівняння f′(x₀) = k знайдіть абсцису, потім підставте її у функцію', f'y′ = {P([2 * a, b])} = {fmt(k)} ⇒ x₀ = {fmt(x0)}; y₀ = f({fmt(x0)}) = {fmt(y0)}')
    kind = rng.choice(['origin', 'cubic', 'perp'])
    if kind == 'origin':
        r = rng.choice([1, 2, 3, 4, 5]); c = r * r; pos = rng.random() < .5
        ans = 2 * r if pos else -2 * r
        wr = [(-ans, f'обрано дотичну з {"від’ємним" if pos else "додатним"} кутовим коефіцієнтом'), (F(r) if pos else F(-r), 'названо абсцису точки дотику'), (F(c), 'узято вільний член'), (F(2 * c), 'похідну обчислено в точці x = c'), (F(ans, 2), 'пропущено множник 2 у похідній')]
        return T.add(lv, f'Через початок координат проведено дотичну до параболи y = x² + {c}. Знайдіть кутовий коефіцієнт цієї дотичної, якщо він {"додатний" if pos else "від’ємний"}.', ans, wr[:1] + wr[2:], 'точка (0; 0) не лежить на параболі: позначте точку дотику (x₀; x₀² + c) і вимагайте, щоб дотична проходила через початок координат',
                     f'дотична: y = 2x₀(x − x₀) + x₀² + {c}; при x = 0, y = 0: −x₀² + {c} = 0 ⇒ x₀ = ±{r}; k = 2x₀ = {fmt(ans)}')
    if kind == 'cubic':
        p = rng.choice([1, 2, 3]); k = rng.choice([-2, -1, 1, 2, 3]); b = 3 * p * p + k   # f = x³ − (3p² + k)x... f′ = 3x² − b = −k?  шукаємо f′ = k₀
        b = rng.choice([v for v in range(-6, 10)]); k0 = 3 * p * p - b
        co = [1, 0, -b, rng.randint(-4, 4)]
        ask = rng.choice(['cnt', 'pos', 'prod'])
        if ask == 'pos':
            wr = [(F(-p), 'обрано точку з від’ємною абсцисою'), (F(p * p), 'не добуто корінь із x₀²'), (F(k0 + b, 3), 'не добуто корінь: названо x₀²'), (F(3 * p), 'поділено неправильно'), (F(2 * p), 'похідну x³ взято рівною 3x/…')]
            return T.add(lv, f'Дотична до графіка функції y = {P(co)} паралельна прямій y = {P([k0, 1])}. Знайдіть абсцису точки дотику, якщо вона додатна.', F(p), wr[:2] + wr[3:], 'паралельність: f′(x₀) = k; квадратне рівняння дає дві точки — обирайте за умовою', f'y′ = {P([3, 0, -b])} = {fmt(k0)} ⇒ x₀² = {p * p} ⇒ x₀ = ±{p}; додатна: {p}')
        if ask == 'prod':
            wr = [(F(p * p), 'знак: корені ±' + str(p) + ', їхній добуток від’ємний'), (F(0), 'знайдено суму абсцис, а не добуток'), (F(-p), 'названо одну з абсцис'), (F(2 * p), 'знайдено відстань між точками'), (F(-(k0 + b)), 'узято 3x₀² замість x₀²')]
            return T.add(lv, f'До графіка функції y = {P(co)} проведено дві дотичні, паралельні прямій y = {P([k0, 1])}. Знайдіть добуток абсцис точок дотику.', F(-p * p), wr[:4], 'паралельність: f′(x₀) = k', f'y′ = {P([3, 0, -b])} = {fmt(k0)} ⇒ x₀ = ±{p}; добуток −{p * p}')
        d = 2 * p
        wr = [(F(p), 'названо одну абсцису'), (F(0), 'знайдено суму абсцис'), (F(p * p), 'названо x₀²'), (F(4 * p), 'відстань подвоєно'), (F(d * d), 'знайдено квадрат відстані')]
        return T.add(lv, f'До графіка функції y = {P(co)} проведено дві дотичні, паралельні прямій y = {P([k0, 1])}. Знайдіть відстань між абсцисами точок дотику.', F(d), wr[:3] + wr[4:], 'паралельність: f′(x₀) = k', f'y′ = {P([3, 0, -b])} = {fmt(k0)} ⇒ x₀ = ±{p}; відстань {p} − (−{p}) = {d}')
    # perp: дотична перпендикулярна до прямої y = −x/k + m
    for _ in range(200):
        a, b = rng.choice([1, 2, -1]), rng.randint(-5, 5); k = rng.choice([2, 4, -2, -4, 6]); x0 = F(k - b, 2 * a)
        if x0.denominator == 1 and x0 != 0 and b: break
    else: return False
    c = rng.randint(-4, 4); kl = F(-1, k)
    wr = [(F(kl - b, 2 * a) if F(kl - b, 2 * a).denominator in (1, 2, 4) else F(-k - b, 2 * a), 'використано умову паралельності замість перпендикулярності'), (F(-k - b, 2 * a), 'кутовий коефіцієнт дотичної взято з протилежним знаком: k₁·k₂ = −1'), (F(k), 'названо кутовий коефіцієнт дотичної'), (F(k + b, 2 * a), 'знак b змінено під час перенесення'), (F(-b, 2 * a), 'знайдено вершину параболи')]
    ks = f'{M if kl < 0 else ""}x/{abs(k)}' if abs(k) != 1 else f'{M if kl < 0 else ""}x'
    return T.add(lv, f'Дотична до графіка функції y = {P([a, b, c])} перпендикулярна до прямої y = {ks} + 3. Знайдіть абсцису точки дотику.', x0, wr[1:] if wr[0][0] == wr[1][0] else wr, 'перпендикулярні прямі: k₁·k₂ = −1, тому кутовий коефіцієнт дотичної дорівнює −1/k₂',
                 f'кутовий коефіцієнт прямої {ffmt(kl)}, тому k дотичної = {fmt(k)}; y′ = {P([2 * a, b])} = {fmt(k)} ⇒ x₀ = {fmt(x0)}')

def f_extr_seg(T, rng, lv):
    if lv == 2 or rng.random() < .35:
        for _ in range(300):
            lead = rng.choice([1, -1]); p, q, co = cubic_pq(rng, lead); a = rng.randint(-5, 2); b = a + rng.randint(2, 5)
            inside = [t for t in (p, q) if a < t < b]
            if b <= 6 and len(inside) >= 1 and (lv == 2 or len(inside) == 1): break
        else: return False
        big = rng.random() < .5; cand = {a: ev(co, a), b: ev(co, b)}; cand.update({t: ev(co, t) for t in inside})
        ans = max(cand.values()) if big else min(cand.values()); oth = min(cand.values()) if big else max(cand.values())
        outside = [t for t in (p, q) if t not in inside]
        wr = [(oth, f'знайдено {"найменше" if big else "найбільше"} значення'), (max(ev(co, a), ev(co, b)) if big else min(ev(co, a), ev(co, b)), 'порівняно лише значення на кінцях відрізка, критичні точки не перевірено')]
        for t in outside: wr.append((ev(co, t), f'узято значення в критичній точці x = {fmt(t)}, яка не належить відрізку'))
        for t in inside: wr.append((ev(co, t), f'узято значення в критичній точці x = {fmt(t)} без порівняння з кінцями'))
        wr += [(ev(co, a), f'узято значення на лівому кінці: f({fmt(a)})'), (ev(co, b), f'узято значення на правому кінці: f({fmt(b)})'), (F([t for t in cand if cand[t] == ans][0]), 'названо точку, у якій досягається це значення, а не саме значення')]
        return T.add(lv, f'Знайдіть {"найбільше" if big else "найменше"} значення функції f(x) = {P(co)} на відрізку [{fmt(a)}; {fmt(b)}].', ans, wr, 'обчисліть значення функції на кінцях відрізка та в критичних точках, що належать відрізку, і порівняйте їх',
                     f'f′(x) = {P(dco(co))} = 0 при x = {fmt(p)}, x = {fmt(q)}; ' + '; '.join(f'f({fmt(t)}) = {fmt(v)}' for t, v in sorted(cand.items())) + f'; відповідь {fmt(ans)}')
    kind = rng.choice(['xax', 'sqrt', 'xax_max'])
    if kind in ('xax', 'xax_max'):
        a = rng.choice([2, 3, 4, 5, 6]); b = a * rng.choice([2, 3, 4]); f = lambda x: F(x) + F(a * a, x)
        if kind == 'xax':
            ans = F(2 * a)
            wr = [(f(1), 'узято значення на лівому кінці відрізка'), (f(b), 'узято значення на правому кінці відрізка'), (F(a), 'названо точку мінімуму, а не значення функції'), (F(a * a), 'узято вільний параметр a²'), (F(0), 'похідну прирівняно до нуля і цей нуль прийнято за відповідь')]
            return T.add(lv, f'Знайдіть найменше значення функції f(x) = x + {a * a}/x на відрізку [1; {b}].', ans, wr, 'f′(x) = 1 − a²/x² = 0 при x = a (x > 0); порівняйте значення в цій точці та на кінцях', f'f′(x) = 1 − {a * a}/x² = 0 ⇒ x = {a}; f(1) = {fmt(f(1))}, f({a}) = {2 * a}, f({b}) = {ffmt(f(b))}; найменше {2 * a}')
        ans = max(f(1), f(b))
        wr = [(F(2 * a), 'знайдено найменше значення'), (min(f(1), f(b)), 'узято значення на іншому кінці відрізка'), (F(b), 'названо кінець відрізка'), (F(a * a), 'узято параметр a²'), (F(a * a) + b, 'дріб a²/x не обчислено')]
        return T.add(lv, f'Знайдіть найбільше значення функції f(x) = x + {a * a}/x на відрізку [1; {b}].', ans, wr, 'єдина критична точка x = a — точка мінімуму, тому найбільше значення досягається на одному з кінців', f'f(1) = {fmt(f(1))}, f({a}) = {2 * a}, f({b}) = {ffmt(f(b))}; найбільше {fmt(ans)}')
    k = rng.choice([1, 2, 3]); r = rng.choice([v for v in (2, 3, 4, 5) if v > k]); b = r * r    # f = 2k√x − x на [0; b]: максимум у x = k², f = k²
    fb = 2 * k * r - b; big = rng.random() < .5; ans = F(k * k) if big else F(min(0, fb))
    wr = [(F(min(0, fb)) if big else F(k * k), f'знайдено {"найменше" if big else "найбільше"} значення'), (F(fb), 'узято значення на правому кінці відрізка'), (F(0), 'узято значення на лівому кінці відрізка'), (F(k), 'названо √x у критичній точці'), (F(2 * k * k), 'значення в критичній точці обчислено без віднімання x')]
    return T.add(lv, f'Знайдіть {"найбільше" if big else "найменше"} значення функції f(x) = {2 * k}√x − x на відрізку [0; {b}].', ans, wr, 'f′(x) = k/√x − 1; критична точка x = k²; обов’язково порівняйте зі значеннями на кінцях', f'f′(x) = {k}/√x − 1 = 0 ⇒ x = {k * k}; f(0) = 0, f({k * k}) = {k * k}, f({b}) = {fmt(fb)}; відповідь {fmt(ans)}')

def f_anti_point(T, rng, lv):
    Fco = [rng.choice([1, 2, -1]), rng.randint(-3, 3), rng.choice([v for v in range(-5, 6) if v]), 0]; f = dco(Fco); x0 = rng.choice([-1, 1, 2]); y0 = rng.randint(-6, 8); C = y0 - ev(Fco, x0)
    x1 = rng.choice([v for v in (-2, -1, 0, 1, 2, 3) if v != x0])
    if C == 0: return False
    kind = rng.choice(['val', 'C'])
    if kind == 'C':
        wr = [(F(y0), 'сталу C прийнято рівною заданому значенню первісної'), (-C, 'знак змінено'), (ev(Fco, x0), 'обчислено F без сталої в заданій точці'), (y0 + ev(Fco, x0), 'значення додано замість віднімання'), (y0 - ev(f, x0), 'у рівняння підставлено саму функцію f, а не первісну')]
        return T.add(lv, f'Первісна F функції f(x) = {P(f)} задовольняє умову F({fmt(x0)}) = {fmt(y0)}. Знайдіть значення F(0).', C, wr, 'F(x) = (первісна без сталої) + C; сталу C знаходять з умови; F(0) = C', f'F(x) = {P(Fco)} + C; F({fmt(x0)}) = {fmt(ev(Fco, x0))} + C = {fmt(y0)} ⇒ C = {fmt(C)}; F(0) = {fmt(C)}')
    ans = ev(Fco, x1) + C
    wr = [(ev(Fco, x1), 'сталу C не враховано'), (ev(Fco, x1) - C, 'знак сталої C змінено'), (ev(Fco, x1) + y0, 'сталу C прийнято рівною заданому значенню'), (ev(f, x1), 'обчислено значення самої функції f'), (F(C), 'названо сталу C')]
    return T.add(lv, f'Первісна F функції f(x) = {P(f)} задовольняє умову F({fmt(x0)}) = {fmt(y0)}. Знайдіть F({fmt(x1)}).', ans, wr, 'F(x) = (первісна без сталої) + C; сталу C знаходять з умови', f'F(x) = {P(Fco)} + C; F({fmt(x0)}) = {fmt(y0)} ⇒ C = {fmt(C)}; F({fmt(x1)}) = {fmt(ev(Fco, x1))} + {pn(C)} = {fmt(ans)}')

def f_area_parab(T, rng, lv):
    r1 = rng.randint(-3, 1); w = rng.choice([2, 3, 4, 6]); r2 = r1 + w; a = rng.choice([1, 1, 3]) if w != 6 else 1
    co = [-a, a * (r1 + r2), -a * r1 * r2]           # y = −a(x − r1)(x − r2) ≥ 0 між коренями
    ans = F(a * w ** 3, 6); top = F(a * w * w, 4)
    wr = [(F(a * w ** 3, 3), 'у формулі пропущено множник 1/2'), (top * w, 'фігуру замінено прямокутником (основа × найбільша висота)'), (top * w / 2, 'фігуру замінено трикутником (половина добутку основи на висоту)'), (-ans, 'площа не може бути від’ємною: межі інтегрування переставлено'), (F(w), 'знайдено лише довжину основи — відстань між нулями')]
    return T.add(lv, f'Знайдіть площу фігури, обмеженої параболою y = {P(co)} і віссю x.', ans, wr, 'межі інтегрування — нулі функції; площа дорівнює інтегралу від функції між ними',
                 f'нулі: x = {fmt(r1)}, x = {fmt(r2)}; S = ∫({P(co)})dx від {fmt(r1)} до {fmt(r2)} = {fmt(ans)}')

def f_area_between(T, rng, lv):
    kind = rng.choice(['line', 'line', 'hor']) if lv == 2 else rng.choice(['two', 'two', 'line3'])
    if kind == 'line':
        p = rng.randint(-3, 1); w = rng.choice([2, 3, 4, 6]); q = p + w; k, b = p + q, -p * q   # x² = kx + b
        ans = F(w ** 3, 6)
        wr = [(F(w ** 3, 3), 'пропущено множник 1/2 під час інтегрування'), (integ([1, 0, 0], p, q), 'знайдено площу лише під параболою, без віднімання від площі під прямою'), (integ([k, b], p, q), 'знайдено площу лише під прямою'), (-ans, 'від нижньої функції віднято верхню: площа не може бути від’ємною'), (F(w), 'знайдено лише відстань між абсцисами точок перетину')]
        return T.add(lv, f'Знайдіть площу фігури, обмеженої параболою y = x² і прямою y = {P([k, b])}.', ans, wr, 'S = ∫(верхня − нижня)dx між абсцисами точок перетину; тут зверху пряма',
                     f'x² = {P([k, b])} ⇒ x = {fmt(p)}, x = {fmt(q)}; S = ∫({P([-1, k, b])})dx від {fmt(p)} до {fmt(q)} = {fmt(ans)}')
    if kind == 'hor':
        r = rng.choice([1, 2, 3]); c = rng.randint(-3, 3); d = c + r * r
        ans = F(4 * r ** 3, 3)
        wr = [(F(2 * r ** 3, 3), 'проінтегровано лише від 0 до ' + str(r) + ' — половина фігури'), (F(2 * r * r * r), 'фігуру замінено прямокутником зі сторонами 2r і r²'), (F(2 * r ** 3, 1) - F(4 * r ** 3, 3), 'знайдено площу під параболою (доповнення до прямокутника)'), (-ans, 'від нижньої функції віднято верхню'), (F(8 * r ** 3, 3), 'результат подвоєно зайвий раз')]
        return T.add(lv, f'Знайдіть площу фігури, обмеженої параболою y = {P([1, 0, c])} і прямою y = {fmt(d)}.', ans, wr, 'S = ∫(верхня − нижня)dx; фігура симетрична відносно осі y, тому можна подвоїти інтеграл від 0',
                     f'{P([1, 0, c])} = {fmt(d)} ⇒ x = ±{r}; S = ∫({r * r} − x²)dx від −{r} до {r} = {fmt(ans)}')
    if kind == 'two':
        r = rng.choice([1, 2, 3]); a1, a2 = rng.choice([(1, 1), (1, 2), (2, 1), (1, 3)]); c = rng.randint(-2, 3); top_c = c + (a1 + a2) * r * r
        ans = F(4 * (a1 + a2) * r ** 3, 3)
        wr = [(ans / 2, 'проінтегровано лише половину фігури (від 0 до ' + str(r) + ')'), (F(2 * (a1 + a2) * r ** 3), 'фігуру замінено прямокутником'), (F(4 * a1 * r ** 3, 3), 'враховано лише одну з парабол'), (-ans, 'від нижньої функції віднято верхню'), (ans * 2, 'результат подвоєно зайвий раз')]
        return T.add(lv, f'Знайдіть площу фігури, обмеженої параболами y = {P([a1, 0, c])} та y = {P([-a2, 0, top_c])}.', ans, wr, 'знайдіть абсциси точок перетину й проінтегруйте різницю (верхня − нижня)',
                     f'{P([a1, 0, c])} = {P([-a2, 0, top_c])} ⇒ x² = {r * r} ⇒ x = ±{r}; S = ∫({P([-(a1 + a2), 0, (a1 + a2) * r * r])})dx від −{r} до {r} = {fmt(ans)}')
    # line3: парабола y = −x² + c і пряма y = kx + b → площа сегмента (q − p)³/6
    p = rng.randint(-3, 0); w = rng.choice([2, 3, 4, 6]); q = p + w; m = rng.randint(1, 6)
    k, b = -(p + q), p * q + m           # −x² + m = kx + b ⇔ x² + kx + (b − m) = 0 з коренями p, q
    ans = F(w ** 3, 6)
    wr = [(F(w ** 3, 3), 'пропущено множник 1/2 під час інтегрування'), (integ([-1, 0, m], p, q), 'знайдено інтеграл лише від параболи'), (-ans, 'від нижньої функції віднято верхню'), (F(w * w, 2), 'інтегрування замінено формулою площі трикутника'), (F(w), 'знайдено відстань між точками перетину')]
    return T.add(lv, f'Знайдіть площу фігури, обмеженої параболою y = {P([-1, 0, m])} і прямою y = {P([k, b])}.', ans, wr, 'S = ∫(верхня − нижня)dx між точками перетину; тут зверху парабола (гілки вниз)',
                 f'{P([-1, 0, m])} = {P([k, b])} ⇒ x = {fmt(p)}, x = {fmt(q)}; S = ∫({P([-1, -k, m - b])})dx від {fmt(p)} до {fmt(q)} = {fmt(ans)}')

def f_NL(T, rng, lv):
    a = rng.randint(-3, 1); b = a + rng.randint(1, 3); c = b + rng.randint(1, 3); I1, I2 = rng.choice([v for v in range(-6, 9) if v]), rng.choice([v for v in range(-6, 9) if v])
    kind = rng.choice(['F', 'add', 'rev'] if lv == 2 else ['lin', 'sub', 'lin2'])
    if kind == 'F':
        Fa, Fb = rng.randint(-7, 7), rng.randint(-7, 7)
        if Fa == Fb or Fa == 0: return False
        wr = [(Fa - Fb, 'віднімання виконано у зворотному порядку'), (Fa + Fb, 'значення первісної додано'), (F(Fb), 'нижню межу не враховано'), (F(Fb - Fa, b - a) if (Fb - Fa) % (b - a) == 0 and b - a > 1 else F(Fb * Fa), 'різницю поділено на довжину проміжку' if (Fb - Fa) % (b - a) == 0 and b - a > 1 else 'значення перемножено'), ((Fb - Fa) * (b - a), 'різницю помножено на довжину проміжку')]
        return T.add(lv, f'Функція F є первісною для функції f на всій числовій прямій, причому F({fmt(a)}) = {fmt(Fa)} і F({fmt(b)}) = {fmt(Fb)}. Обчисліть інтеграл від функції f у межах від {fmt(a)} до {fmt(b)}.', Fb - Fa, wr, 'формула Ньютона — Лейбніца: ∫f(x)dx від a до b дорівнює F(b) − F(a)', f'F({fmt(b)}) − F({fmt(a)}) = {fmt(Fb)} − {pn(Fa)} = {fmt(Fb - Fa)}')
    if kind == 'add':
        wr = [(I1 - I2, 'інтеграли віднято замість додавання'), (I2 - I1, 'інтеграли віднято замість додавання'), (I1 * I2, 'інтеграли перемножено'), (-(I1 + I2), 'знак змінено'), (F(I1), 'другий проміжок не враховано')]
        return T.add(lv, f'Відомо, що інтеграл від функції f у межах від {fmt(a)} до {fmt(b)} дорівнює {fmt(I1)}, а в межах від {fmt(b)} до {fmt(c)} дорівнює {fmt(I2)}. Знайдіть інтеграл від f у межах від {fmt(a)} до {fmt(c)}.', I1 + I2, wr, 'адитивність: інтеграл по [a; c] дорівнює сумі інтегралів по [a; b] і [b; c]', f'{fmt(I1)} + {pn(I2)} = {fmt(I1 + I2)}')
    if kind == 'rev':
        k = rng.choice([2, 3, 4, 5])
        wr = [(k * I1, 'не враховано, що перестановка меж змінює знак інтеграла'), (-I1, 'пропущено сталий множник ' + str(k)), (F(I1), 'ні множник, ні перестановку меж не враховано'), (F(-I1, k) if I1 % k == 0 else F(k - I1), 'поділено на k замість множення' if I1 % k == 0 else 'множник додано'), (-k * I1 - 1, 'помилка в обчисленнях')]
        return T.add(lv, f'Відомо, що інтеграл від функції f у межах від {fmt(a)} до {fmt(b)} дорівнює {fmt(I1)}. Знайдіть інтеграл від функції {k}f(x) у межах від {fmt(b)} до {fmt(a)}.', -k * I1, wr[:4], 'сталий множник виносять за знак інтеграла; якщо межі переставити, інтеграл змінює знак', f'{k}·(−{pn(I1)}) = {fmt(-k * I1)}')
    if kind == 'lin':
        k = rng.choice([2, 3, -2]); m = rng.choice([1, 2, 3, 4, -1]); L = b - a; ans = k * I1 + m * L
        wr = [(k * I1 + m, f'інтеграл від сталої {fmt(m)} дорівнює {fmt(m)}·(b − a), а не {fmt(m)}'), (F(k * I1), 'інтеграл від сталого доданка не враховано'), (k * (I1 + m * L), 'сталий доданок теж помножено на k'), (I1 + m * L, 'пропущено множник k'), (k * I1 - m * L, 'знак другого доданка змінено')]
        return T.add(lv, f'Відомо, що інтеграл від функції f у межах від {fmt(a)} до {fmt(b)} дорівнює {fmt(I1)}. Знайдіть інтеграл від функції {fmt(k)}f(x) {sg(m)} {abs(m)} у тих самих межах.', ans, wr, 'інтеграл суми дорівнює сумі інтегралів; інтеграл від сталої c по [a; b] дорівнює c(b − a)', f'{fmt(k)}·{pn(I1)} + {pn(m)}·({fmt(b)} − {pn(a)}) = {fmt(ans)}')
    if kind == 'sub':
        tot = I1 + I2
        wr = [(tot + I1, 'інтеграли додано замість віднімання'), (I1 - tot, 'віднімання виконано у зворотному порядку'), (F(tot), 'частину проміжку не віднято'), (-I2 - 2 * I1, 'знаки переплутано'), (F(I1), 'названо відомий інтеграл по першій частині')]
        return T.add(lv, f'Відомо, що інтеграл від функції f у межах від {fmt(a)} до {fmt(c)} дорівнює {fmt(tot)}, а в межах від {fmt(a)} до {fmt(b)} дорівнює {fmt(I1)}. Знайдіть інтеграл від f у межах від {fmt(b)} до {fmt(c)}.', I2, wr[:3] + wr[4:], 'адитивність: інтеграл по [a; c] = інтеграл по [a; b] + інтеграл по [b; c]', f'{fmt(tot)} − {pn(I1)} = {fmt(I2)}')
    g1, g2 = rng.choice([v for v in range(-5, 6) if v]), rng.choice([2, 3]); h = rng.choice([2, 3, -1]); ans = g2 * I1 - h * g1
    wr = [(g2 * I1 + h * g1, 'другий інтеграл додано замість віднімання'), (I1 - g1, 'сталі множники не враховано'), (g2 * (I1 - g1), 'обидва інтеграли помножено на перший множник'), (h * I1 - g2 * g1, 'множники переставлено місцями'), (-ans, 'знак змінено')]
    return T.add(lv, f'Інтеграл від функції f у межах від {fmt(a)} до {fmt(b)} дорівнює {fmt(I1)}, а інтеграл від функції g у тих самих межах дорівнює {fmt(g1)}. Знайдіть інтеграл від функції {g2}f(x) {sg(-h)} {abs(h)}g(x) у цих межах.', ans, wr, 'лінійність інтеграла: ∫(αf + βg) = α∫f + β∫g', f'{g2}·{pn(I1)} − {pn(h)}·{pn(g1)} = {fmt(ans)}')

def f_from_deriv(T, rng, lv):
    """функцію не задано, задано лише похідну"""
    p = rng.randint(-5, 2); q = p + rng.randint(1, 6); a = rng.choice([1, 1, -1, 2]); d = [a, -a * (p + q), a * p * q]
    kind = rng.choice(['dec', 'inc', 'xmin', 'xmax'])
    xmax, xmin = (p, q) if a > 0 else (q, p)
    base = f'Похідна функції f, визначеної на всій числовій прямій, дорівнює f′(x) = {P(d)}. '
    fact = f'f′(x) = {fmt(a) if a != 1 else ""}(x {sg(-p)} {abs(p)})(x {sg(-q)} {abs(q)}): знаки {"+ − +" if a > 0 else "− + −"}'.replace('(x + 0)', 'x').replace('(x − 0)', 'x')
    if kind in ('xmin', 'xmax'):
        ans, oth = (xmin, xmax) if kind == 'xmin' else (xmax, xmin)
        wr = [(F(oth), f'названо точку {"максимуму" if kind == "xmin" else "мінімуму"}: зміну знака похідної визначено навпаки'), (F(p + q, 2), 'названо вершину параболи f′ — це точка екстремуму похідної, а не функції'), (F(-ans), 'знак кореня змінено'), (ev(d, 0), 'узято значення f′(0)'), (F(p + q), 'названо суму нулів похідної')]
        return T.add(lv, base + f'Знайдіть точку {"мінімуму" if kind == "xmin" else "максимуму"} функції f.', F(ans), wr, 'точка мінімуму — там, де f′ змінює знак з «−» на «+»; точка максимуму — з «+» на «−»', fact + f'; точка {"мінімуму" if kind == "xmin" else "максимуму"} x = {fmt(ans)}')
    inner = (kind == 'dec') == (a > 0)
    two = setstr([(None, F(p), False, True), (F(q), None, True, False)]).replace(' ∪ ', ' і ')
    ans = I(p, q) if inner else two
    v = F(p + q, 2)
    wr = [(two if inner else I(p, q), f'на цих проміжках функція {"зростає" if kind == "dec" else "спадає"}'), (I(None, v, False, True) if a > 0 else I(v, None), 'записано проміжок спадання самої похідної f′ (параболи), а не функції f'), (I(v, None) if a > 0 else I(None, v, False, True), 'записано проміжок зростання похідної f′, а не функції f'), (I(-q, -p) if inner else setstr([(None, F(-q), False, True), (F(-p), None, True, False)]).replace(' ∪ ', ' і '), 'знаки нулів похідної змінено')]
    return T.add(lv, base + f'Укажіть проміжок (проміжки) {"спадання" if kind == "dec" else "зростання"} функції f.', ans, wr, 'f спадає там, де f′(x) ≤ 0, і зростає там, де f′(x) ≥ 0 — не плутайте з монотонністю самої похідної', fact + f'; відповідь: {ans}')

def f_kin_int(T, rng, lv):
    if lv == 2:
        a, b = rng.choice([2, 4, 6, 3]), rng.randint(1, 8); t1 = rng.randint(0, 2); t2 = t1 + rng.randint(1, 3); v = [a, b]; ans = integ(v, t1, t2)
        wr = [(ev(v, t2) - ev(v, t1), 'знайдено зміну швидкості, а не шлях'), (ev(v, t2) * (t2 - t1), 'кінцеву швидкість помножено на час — так можна лише при сталій швидкості'), (integ(v, 0, t2), 'інтеграл обчислено від 0, а не від початку заданого проміжку') if t1 else (ev(v, t2), 'названо швидкість наприкінці проміжку'), (ev(v, t1) * (t2 - t1), 'початкову швидкість помножено на час'), (F(a), 'названо прискорення')]
        return T.add(lv, f'Швидкість точки, що рухається прямолінійно, змінюється за законом v(t) = {P(v, "t")} (v — у м/с, t — у секундах). Знайдіть шлях (у метрах), який точка пройшла за проміжок часу від t = {t1} с до t = {t2} с.', ans, wr, 'шлях — це інтеграл від швидкості за часом (площа під графіком швидкості)', f's = ∫({P(v, "t")})dt від {t1} до {t2} = {fmt(ans)}')
    kind = rng.choice(['stop', 'quad', 'turn'])
    if kind == 'stop':
        a = rng.choice([2, 4, 5]); T0 = rng.choice([2, 3, 4, 5, 6]); v0 = a * T0; ans = F(v0 * T0, 2)
        wr = [(F(v0 * T0), 'початкову швидкість помножено на час без урахування гальмування'), (F(T0), 'названо час до зупинки, а не шлях'), (F(v0), 'названо початкову швидкість'), (F(v0 * T0, 4), 'результат поділено на 2 зайвий раз'), (F(v0 * v0, a), 'у формулі v₀²/(2a) пропущено 2')]
        return T.add(lv, f'Автомобіль гальмує, і його швидкість змінюється за законом v(t) = {v0} − {a}t (v — у м/с, t — у секундах). Який шлях (у метрах) пройде автомобіль від початку гальмування до повної зупинки?', ans, wr, 'спочатку знайдіть момент зупинки (v = 0), а потім проінтегруйте швидкість від 0 до цього моменту', f'v = 0 при t = {T0}; s = ∫({v0} − {a}t)dt від 0 до {T0} = {v0}·{T0} − {a}·{T0}²/2 = {fmt(ans)}')
    if kind == 'quad':
        co = [3, rng.choice([2, 4, -2, 6]), rng.randint(1, 6)]; t2 = rng.choice([2, 3]); ans = integ(co, 0, t2)
        if ans <= 0: return False
        wr = [(ev(co, t2), 'названо швидкість наприкінці руху'), (ev(co, t2) * t2, 'кінцеву швидкість помножено на час'), (ev(dco(co), t2), 'знайдено прискорення'), (ev(co + [0], t2), 'первісну знайдено без ділення на нові показники'), (integ(co, 0, t2) - co[-1] * t2, 'сталий доданок швидкості не проінтегровано')]
        return T.add(lv, f'Швидкість точки, що рухається прямолінійно, змінюється за законом v(t) = {P(co, "t")} (v — у м/с). Знайдіть шлях (у метрах), пройдений точкою за перші {t2} с руху.', ans, wr, 'шлях — інтеграл від швидкості: s = ∫v(t)dt', f's = ∫({P(co, "t")})dt від 0 до {t2} = {P(ico(co), "t")} при t = {t2}: {fmt(ans)}')
    a = rng.choice([2, 4, 6]); t0 = rng.choice([1, 2, 3]); t2 = t0 + rng.choice([1, 2, 3]); v = [a, -a * t0]     # v = a(t − t0): змінює знак
    disp = integ(v, 0, t2); path = -integ(v, 0, t0) + integ(v, t0, t2)
    if disp == path: return False
    wr = [(disp, 'знайдено переміщення (інтеграл зі знаком), а не шлях: до моменту зміни напряму точка рухалась у протилежний бік'), (abs(integ(v, t0, t2)), 'враховано лише рух після зміни напряму'), (abs(integ(v, 0, t0)), 'враховано лише рух до зміни напряму'), (abs(ev(v, t2)) * t2, 'кінцеву швидкість помножено на час'), (path * 2, 'результат подвоєно')]
    return T.add(lv, f'Швидкість точки, що рухається вздовж прямої, змінюється за законом v(t) = {P(v, "t")} (v — у м/с). Знайдіть шлях (у метрах), пройдений точкою за перші {t2} с руху.', path, wr, 'якщо швидкість змінює знак, шлях дорівнює інтегралу від |v(t)|: частини руху «туди» й «назад» додають',
                 f'v = 0 при t = {t0}; до цього моменту шлях {ffmt(-integ(v, 0, t0))} м, після — {ffmt(integ(v, t0, t2))} м; разом {ffmt(path)} м')

# ================= L3 =================
def f_param_mono(T, rng, lv):
    kind = rng.choice(['inc', 'dec', 'cnt', 'noext'])
    k = rng.choice([1, 2, 3, 4]); b3 = 3 * k * k      # f = x³ + a x² + b3·x: f′ = 3x² + 2ax + 3k²; D/4 = a² − 9k² ≤ 0 ⇔ |a| ≤ 3k
    if kind == 'inc':
        ans = I(-3 * k, 3 * k)
        wr = [(I(-3 * k, 3 * k, False, False), 'при D = 0 похідна дорівнює нулю лише в одній точці, і функція все одно зростає, тому кінці входять'), (setstr([(None, F(-3 * k), False, True), (F(3 * k), None, True, False)]), 'знак нерівності для дискримінанта обрано протилежний (D ≥ 0)'), (I(-k, k), f'у дискримінанті пропущено множник: D/4 = a² − {9 * k * k}'), (I(None, 3 * k, False, True), f'розв’язано a ≤ {3 * k} без урахування модуля'), (I(-9 * k * k, 9 * k * k), 'не добуто корінь')]
        return T.add(lv, f'Знайдіть усі значення параметра a, при яких функція f(x) = x³ + ax² + {b3}x зростає на всій числовій прямій.', ans, wr, 'функція зростає на R, якщо f′(x) ≥ 0 для всіх x: для квадратного тричлена з додатним старшим коефіцієнтом це означає D ≤ 0', f'f′(x) = 3x² + 2ax + {b3}; D/4 = a² − {9 * k * k} ≤ 0 ⇒ |a| ≤ {3 * k}')
    if kind == 'dec':
        ans = I(-3 * k, 3 * k)
        wr = [(I(-3 * k, 3 * k, False, False), 'при D = 0 похідна дорівнює нулю лише в одній точці, функція все одно спадає, тому кінці входять'), (setstr([(None, F(-3 * k), False, True), (F(3 * k), None, True, False)]), 'знак нерівності для дискримінанта обрано протилежний'), (I(-k, k), 'у дискримінанті пропущено множник'), ('таких значень немає', 'старший коефіцієнт похідної від’ємний, тому умова D ≤ 0 можлива'), (I(None, 3 * k, False, True), 'розв’язано без урахування модуля')]
        return T.add(lv, f'Знайдіть усі значення параметра a, при яких функція f(x) = −x³ + ax² − {b3}x спадає на всій числовій прямій.', ans, wr, 'функція спадає на R, якщо f′(x) ≤ 0 для всіх x: для тричлена з від’ємним старшим коефіцієнтом це означає D ≤ 0', f'f′(x) = −3x² + 2ax − {b3}; D/4 = a² − {9 * k * k} ≤ 0 ⇒ |a| ≤ {3 * k}')
    if kind == 'cnt':
        ans = 6 * k + 1
        wr = [(6 * k - 1, 'кінці проміжку не враховано, хоча нерівність нестрога'), (6 * k, 'пропущено значення a = 0 або один із кінців'), (3 * k + 1, 'враховано лише невід’ємні значення a'), (2 * k + 1, 'у дискримінанті пропущено множник'), (6 * k + 2, 'зайве значення зараховано')]
        return T.add(lv, f'Скільки цілих значень параметра a, при яких функція f(x) = x³ + ax² + {b3}x зростає на всій числовій прямій?', ans, wr, 'f′(x) ≥ 0 для всіх x ⇔ D ≤ 0 (нерівність нестрога)', f'f′(x) = 3x² + 2ax + {b3}; a² ≤ {9 * k * k} ⇒ −{3 * k} ≤ a ≤ {3 * k}; цілих значень {ans}')
    ans = I(-3 * k, 3 * k)
    wr = [(I(-3 * k, 3 * k, False, False), 'при D = 0 похідна має один нуль, але знака не змінює — екстремуму немає, тому кінці входять'), (setstr([(None, F(-3 * k), False, False), (F(3 * k), None, False, False)]), 'знайдено значення a, при яких функція має два екстремуми'), (I(-k, k), 'у дискримінанті пропущено множник'), ('{' + fmt(-3 * k) + '; ' + fmt(3 * k) + '}', 'враховано лише випадок D = 0')]
    return T.add(lv, f'Знайдіть усі значення параметра a, при яких функція f(x) = x³ + ax² + {b3}x не має точок екстремуму.', ans, wr, 'екстремуми є лише тоді, коли похідна змінює знак, тобто D > 0; при D ≤ 0 екстремумів немає', f'f′(x) = 3x² + 2ax + {b3}; D/4 = a² − {9 * k * k} ≤ 0 ⇒ |a| ≤ {3 * k}')

def f_deriv_factored(T, rng, lv):
    roots = sorted(rng.sample(range(-5, 6), rng.choice([3, 4]))); mult = [rng.choice([1, 1, 2, 3]) for _ in roots]; lead = rng.choice([1, -1])
    if all(m % 2 == 1 for m in mult) and rng.random() < .7: mult[rng.randrange(len(mult))] = 2
    def sgn(x):
        s = lead
        for r, m in zip(roots, mult): s *= (1 if x > r else -1) ** m
        return s
    pts = [roots[0] - 1] + [F(a + b, 2) for a, b in zip(roots, roots[1:])] + [roots[-1] + 1]; sg_ = [sgn(x) for x in pts]
    xmax = [r for i, r in enumerate(roots) if sg_[i] > 0 > sg_[i + 1]]; xmin = [r for i, r in enumerate(roots) if sg_[i] < 0 < sg_[i + 1]]
    fac = (M if lead < 0 else '') + ''.join((('x' if r == 0 else f'(x {sg(-r)} {abs(r)})') + (sup(m) if m > 1 else '')) for r, m in zip(roots, mult))
    signs = 'знаки похідної на проміжках зліва направо: ' + ' '.join('+' if s > 0 else '−' for s in sg_)
    kind = rng.choice(['cnt', 'max', 'min', 'sum'])
    base = f'Похідна функції f, визначеної на всій числовій прямій, дорівнює f′(x) = {fac}. '
    trap = 'у нулі парної кратності похідна знака не змінює — екстремуму там немає'
    if kind == 'cnt':
        ans = len(xmax) + len(xmin)
        wr = [(len(roots), 'пораховано всі нулі похідної, хоча в нулях парної кратності знак не змінюється'), (sum(mult), 'додано кратності нулів'), (len(xmax), 'пораховано лише точки максимуму'), (len(xmin), 'пораховано лише точки мінімуму'), (len(roots) - ans, 'пораховано нулі, у яких екстремуму немає')]
        return T.add(lv, base + 'Скільки точок екстремуму має функція f?', ans, wr, trap, signs + f'; знак змінюється в {ans} точ{"ці" if ans == 1 else "ках"}')
    if kind in ('max', 'min'):
        lst = xmax if kind == 'max' else xmin; oth = xmin if kind == 'max' else xmax
        if len(lst) != 1: return False
        wr = [(F(o), f'це точка {"мінімуму" if kind == "max" else "максимуму"}') for o in oth] + [(F(r), 'у цій точці похідна дорівнює нулю, але знака не змінює — екстремуму немає') for r in roots if r not in xmax + xmin]
        wr += [(F(-lst[0]), 'знак змінено'), (F(sum(roots)), 'додано всі нулі похідної')]
        return T.add(lv, base + f'Знайдіть точку {"максимуму" if kind == "max" else "мінімуму"} функції f.', F(lst[0]), wr, trap + '; максимум — зміна знака з «+» на «−»', signs + f'; точка {"максимуму" if kind == "max" else "мінімуму"} x = {fmt(lst[0])}')
    ext = xmax + xmin
    if len(ext) < 2: return False
    ans = sum(ext)
    wr = [(sum(roots), 'додано всі нулі похідної, зокрема ті, де знак не змінюється'), (sum(xmax), 'додано лише точки максимуму'), (sum(xmin), 'додано лише точки мінімуму'), (F(len(ext)), 'знайдено кількість точок екстремуму, а не суму'), (-ans, 'знаки нулів змінено')]
    return T.add(lv, base + 'Знайдіть суму всіх точок екстремуму функції f.', ans, wr, trap, signs + f'; точки екстремуму: {", ".join(fmt(x) for x in sorted(ext))}; сума {fmt(ans)}')

def f_int_prop(T, rng, lv):
    kind = rng.choice(['odd', 'abs', 'lin', 'trig', 'abs2'])
    if kind == 'odd':
        a = rng.choice([1, 2, 3]); c3, c1 = rng.choice([1, 2, 4, -3, 5]), rng.choice([3, -2, 5, 7, -4]); c2, c0 = rng.choice([3, 6, -3]), rng.choice([1, 2, -1, 4]); co = [c3, c2, c1, c0]
        ans = integ(co, -a, a)
        wr = [(F(0), 'увесь інтеграл прийнято рівним нулю, хоча нулю дорівнює лише інтеграл від непарних доданків'), (ans / 2, 'парну частину проінтегровано лише від 0 до a без подвоєння'), (2 * integ(co, 0, a), 'подвоєно інтеграл від усієї функції на [0; a], включно з непарними доданками'), (integ(co, 0, a), 'обчислено інтеграл від 0 до a'), (-ans, 'знак змінено')]
        return T.add(lv, f'Обчисліть інтеграл ∫ ({P(co)}) dx у межах від −{a} до {a}.', ans, wr, 'на симетричному проміжку інтеграл від непарної функції дорівнює 0, а від парної — подвоєному інтегралу від 0 до a', f'непарні доданки дають 0; ∫({P([c2, 0, c0])})dx від −{a} до {a} = 2·({ffmt(integ([c2, 0, c0], 0, a))}) = {fmt(ans)}')
    if kind in ('abs', 'abs2'):
        c = rng.randint(1, 4); a = c - rng.randint(1, 3); b = c + rng.randint(1, 4)
        if kind == 'abs2': a = 0 if a > 0 else a
        ans = F((c - a) ** 2 + (b - c) ** 2, 2); naive = integ([1, -c], a, b)
        if naive == ans or naive == -ans: return False
        wr = [(naive, 'модуль просто відкинуто: проінтегровано x − c без поділу проміжку'), (abs(naive), 'узято модуль від інтеграла замість інтеграла від модуля'), (F((b - c) ** 2, 2), 'враховано лише частину проміжку, де x ≥ c'), (F((c - a) ** 2 + (b - c) ** 2), 'площі трикутників знайдено без множника 1/2'), (F((b - a) ** 2, 2), 'проміжок не поділено точкою x = c')]
        return T.add(lv, f'Обчисліть інтеграл ∫ |x − {c}| dx у межах від {fmt(a)} до {fmt(b)}.', ans, wr, 'модуль розкривають, поділивши проміжок точкою, де підмодульний вираз дорівнює нулю; геометрично це сума площ двох прямокутних трикутників',
                     f'на [{fmt(a)}; {c}] |x − {c}| = {c} − x, на [{c}; {b}] |x − {c}| = x − {c}; площі трикутників {ffmt(F((c - a) ** 2, 2))} і {ffmt(F((b - c) ** 2, 2))}; сума {fmt(ans)}')
    if kind == 'lin':
        k = rng.choice([2, 3]); n = rng.choice([2, 3]); b = rng.choice([-1, 0, 1]); x1, x2 = 0, 1
        t1, t2 = k * x1 + b, k * x2 + b; ans = F(t2 ** (n + 1) - t1 ** (n + 1), k * (n + 1))
        wr = [(F(t2 ** (n + 1) - t1 ** (n + 1), n + 1), f'не поділено на коефіцієнт k = {k} при x'), (F(t2 ** (n + 1) - t1 ** (n + 1), 1) * k / (n + 1), 'помножено на k замість ділення (так роблять під час диференціювання)'), (F(t2 ** n - t1 ** n), 'межі підставлено в саму функцію'), (F(n * k * (t2 ** (n - 1) - t1 ** (n - 1))), 'знайдено похідну замість первісної'), (F(t2 ** (n + 1), k * (n + 1)), 'нижню межу не враховано')]
        return T.add(lv, f'Обчисліть інтеграл ∫ ({P([k, b])}){sup(n)} dx у межах від 0 до 1.', ans, wr, 'первісна для (kx + b)ⁿ дорівнює (kx + b)ⁿ⁺¹/(k(n + 1)) — не забудьте поділити на k', f'F(x) = ({P([k, b])}){sup(n + 1)}/{k * (n + 1)}; F(1) − F(0) = ({t2 ** (n + 1)} − {pn(t1 ** (n + 1))})/{k * (n + 1)} = {fmt(ans)}')
    k = rng.choice([2, 3, 4]); which = rng.choice(['sin', 'cos'])
    if which == 'sin':
        m = rng.choice([1, 2, 3, 4]); ans = F(2 * m, k)          # ∫₀^{π/k} m sin kx dx = m·2/k
        wr = [(F(2 * m), f'не поділено на коефіцієнт k = {k} при x'), (F(2 * m * k), 'помножено на k замість ділення'), (F(0), 'межі підставлено в саму функцію: sin π − sin 0 = 0'), (F(-2 * m, k), 'знак первісної: первісна для sin kx дорівнює −cos kx/k'), (F(m, k), 'cos π − cos 0 обчислено як −1 замість −2')]
        return T.add(lv, f'Обчисліть інтеграл ∫ {m if m > 1 else ""}sin {k}x dx у межах від 0 до π/{k}.', ans, wr, 'первісна для sin kx дорівнює −cos kx/k', f'F(x) = −{m if m > 1 else ""}cos {k}x/{k}; F(π/{k}) − F(0) = {ffmt(F(m, k))} + {ffmt(F(m, k))} = {fmt(ans)}')
    m = rng.choice([1, 2, 3, 4]); ans = F(m, k)                  # ∫₀^{π/(2k)} m cos kx dx = m/k
    wr = [(F(m), f'не поділено на коефіцієнт k = {k} при x'), (F(m * k), 'помножено на k замість ділення'), (F(-m), 'межі підставлено в саму функцію: cos(π/2) − cos 0'), (F(-m, k), 'знак первісної: первісна для cos kx дорівнює sin kx/k'), (F(2 * m, k), 'результат подвоєно')]
    return T.add(lv, f'Обчисліть інтеграл ∫ {m if m > 1 else ""}cos {k}x dx у межах від 0 до π/{2 * k}.', ans, wr, 'первісна для cos kx дорівнює sin kx/k', f'F(x) = {m if m > 1 else ""}sin {k}x/{k}; F(π/{2 * k}) − F(0) = {ffmt(F(m, k))} − 0 = {fmt(ans)}')

FAMS1 = [(f_d_poly, [1]), (f_d_point, [1]), (f_d_table, [1, 2]), (f_anti_poly, [1]), (f_int_poly, [1, 2]), (f_motion, [1, 2, 3]), (f_tangent_slope, [1, 2]), (f_crit, [1, 2]), (f_int_basic, [1, 2]), (f_second, [1]),
         (f_d_product, [2]), (f_d_quot, [2]), (f_d_chain, [2, 3]), (f_tangent_eq, [2]), (f_tangent_par, [2, 3]), (f_extr_seg, [2, 3]), (f_anti_point, [2]), (f_area_parab, [2]), (f_area_between, [2, 3]), (f_NL, [2, 3]), (f_from_deriv, [2]), (f_kin_int, [2, 3]),
         (f_param_mono, [3]), (f_deriv_factored, [3]), (f_int_prop, [3])]
FAMS = FAMS1
